import { RuntimePerformanceMonitor, type RuntimeObservation } from '../runtime-performance-monitor';
import { cancellable, cancellableFrame, MEDIA_LIMITS, validNumber, type CodecFamily, type MediaEnvironment } from '../types';
import { linkAbort } from './range-source';

export interface EncodingAdjustment { maxBitrate?: number; maxFramerate?: number; scaleResolutionDownBy?: number }

/** Operates on caller-owned RTP objects; never changes ICE, TURN, DataChannels or SDP itself. */
export class WebRTCAdapter {
  readonly monitor = new RuntimePerformanceMonitor();
  private previous = new Map<string, any>();
  private updating = Promise.resolve();
  private lifetime = new AbortController();
  private timer?: ReturnType<typeof setTimeout>;
  constructor(private peer: RTCPeerConnection, private sender: RTCRtpSender, private transceiver?: RTCRtpTransceiver) {}
  setCodecPreferences(capabilities: RTCRtpCodec[], priorities: readonly CodecFamily[]) {
    if (!this.transceiver?.setCodecPreferences) return false;
    const family = (codec: RTCRtpCodec) => {
      const name = codec.mimeType.split('/')[1]?.toLowerCase();
      return name === 'h264' ? 'avc' : name === 'h265' ? 'hevc' : name as CodecFamily;
    };
    const media = capabilities.filter(codec => priorities.includes(family(codec)))
      .sort((a, b) => priorities.indexOf(family(a)) - priorities.indexOf(family(b)));
    if (!media.length) return false;
    const repair = capabilities.filter(codec => /\/(rtx|red|ulpfec|flexfec-03)$/i.test(codec.mimeType));
    this.transceiver.setCodecPreferences([...media, ...repair]);
    return true;
  }
  adjust(adjustment: EncodingAdjustment) {
    const run = async () => {
      this.lifetime.signal.throwIfAborted();
      for (const key of ['maxBitrate', 'maxFramerate', 'scaleResolutionDownBy'] as const)
        if (adjustment[key] !== undefined && !validNumber(adjustment[key], 1)) throw new Error('Invalid RTP encoding adjustment');
      const parameters = this.sender.getParameters();
      if (!parameters.encodings?.length) return;
      parameters.encodings = parameters.encodings.map(encoding => ({ ...encoding, ...adjustment }));
      await cancellable(this.sender.setParameters(parameters), this.lifetime.signal);
    };
    const operation = this.updating.then(run);
    this.updating = operation.catch(() => {});
    return operation;
  }
  async sample() {
    const report = await cancellable(this.sender.getStats ? this.sender.getStats() : this.peer.getStats(), this.lifetime.signal);
    const stats = new Map<string, any>(); report.forEach(stat => stats.set(stat.id, stat));
    const observation: Partial<RuntimeObservation> = {};
    for (const stat of stats.values()) {
      const previous = this.previous.get(stat.id), elapsed = previous ? stat.timestamp - previous.timestamp : 0;
      if ((stat.kind || stat.mediaType) === 'video' && elapsed > 0) {
        const encoded = stat.type === 'outbound-rtp', decoded = stat.type === 'inbound-rtp';
        if (encoded && stat.qualityLimitationReason === 'cpu') observation.processingLimited = true;
        if (encoded && stat.qualityLimitationReason === 'bandwidth') {
          observation.networkLimited = true;
          if (observation.processingLimited !== true) observation.processingLimited = false;
        }
        const count = encoded ? 'framesEncoded' : 'framesDecoded', cost = encoded ? 'totalEncodeTime' : 'totalDecodeTime';
        if ((encoded || decoded) && validNumber(stat[count]) && validNumber(previous[count]) && stat[count] >= previous[count]) {
          const frames = stat[count] - previous[count];
          observation[encoded ? 'encodeFps' : 'decodeFps'] = frames * 1000 / elapsed;
          if (frames && validNumber(stat[cost]) && validNumber(previous[cost]) && stat[cost] >= previous[cost])
            this.monitor.record(encoded ? 'encode' : 'decode', (stat[cost] - previous[cost]) * 1000 / frames, frames);
          if (decoded && validNumber(stat.framesDropped) && validNumber(previous.framesDropped) && stat.framesDropped >= previous.framesDropped) {
            observation.droppedFrames = stat.framesDropped - previous.framesDropped;
            observation.totalFrames = frames + observation.droppedFrames;
            this.monitor.observeDropped(stat.framesDropped);
          }
        }
      }
      if (stat.type === 'remote-inbound-rtp') {
        const outbound = stats.get(stat.localId), oldOutbound = this.previous.get(stat.localId);
        if (outbound && oldOutbound && previous && outbound.packetsSent > oldOutbound.packetsSent && stat.packetsLost >= previous.packetsLost)
          observation.packetLoss = Math.min(1, (stat.packetsLost - previous.packetsLost) / (outbound.packetsSent - oldOutbound.packetsSent));
        if (validNumber(stat.roundTripTime)) observation.rttMs = stat.roundTripTime * 1000;
      }
    }
    const transport = [...stats.values()].find(stat => stat.type === 'transport' && stat.selectedCandidatePairId);
    const pair = stats.get(transport?.selectedCandidatePairId);
    if (pair?.state === 'succeeded') {
      if (validNumber(pair.currentRoundTripTime)) observation.rttMs = pair.currentRoundTripTime * 1000;
      if (validNumber(pair.availableOutgoingBitrate)) observation.availableBitrate = pair.availableOutgoingBitrate;
    }
    // Keep only the current report, bounding stats history even across reconnects/SSRC changes.
    this.previous = stats;
    this.monitor.observeNetwork(observation);
    return { observation, metrics: this.monitor.snapshot() };
  }
  start(options: { targetFps: number; maxBitrate: number; active?: () => boolean;
    onError: (error: unknown) => void; onSample?: (sample: Awaited<ReturnType<WebRTCAdapter['sample']>>) => void }) {
    if (this.timer) throw new Error('RTP monitoring already started');
    const tick = async () => {
      try {
        const sample = await this.sample();
        options.onSample?.(sample);
        const current = this.sender.getParameters().encodings?.[0];
        const adjustment = this.monitor.adapt({ ...sample.observation, targetFps: current?.maxFramerate || options.targetFps,
          active: options.active ? options.active() : !!this.sender.track && this.sender.track.enabled && this.sender.track.readyState === 'live',
          demandBitrate: current?.maxBitrate || options.maxBitrate });
        if (adjustment) {
          const encoding = this.sender.getParameters().encodings?.[0];
          if (encoding) await this.adjust({
            maxBitrate: Math.max(64000, Math.min(options.maxBitrate, (encoding.maxBitrate || options.maxBitrate) * adjustment.bitrateFactor)),
            maxFramerate: Math.max(5, Math.min(options.targetFps, (encoding.maxFramerate || options.targetFps) * adjustment.fpsFactor)),
            scaleResolutionDownBy: Math.max(1, Math.min(4, (encoding.scaleResolutionDownBy || 1) / adjustment.resolutionFactor)),
          });
        }
      } catch (error) { if (!this.lifetime.signal.aborted) options.onError(error); }
      if (!this.lifetime.signal.aborted) this.timer = setTimeout(tick, 1000);
    };
    this.timer = setTimeout(tick, 0);
  }
  close() { this.lifetime.abort(); clearTimeout(this.timer); this.previous.clear(); }
}

/** Raw VideoFrames enter the native WebRTC encoder through a generated track. */
export function createProcessedVideoTrack(input: MediaStreamTrack, options: {
  transform: (frame: VideoFrame, signal: AbortSignal) => Promise<VideoFrame>;
  signal?: AbortSignal; environment?: MediaEnvironment;
}) {
  const env: MediaEnvironment = options.environment || globalThis;
  const Processor = env.MediaStreamTrackProcessor, Generator = env.VideoTrackGenerator || env.MediaStreamTrackGenerator;
  if (!Processor || !Generator) throw new Error('Processed video tracks are unavailable in this execution context');
  const link = linkAbort(options.signal), signal = link.controller.signal;
  const processor = new Processor({ track: input, maxBufferSize: 1 });
  const generator = env.VideoTrackGenerator ? new Generator() : new Generator({ kind: 'video' });
  const track: MediaStreamTrack = generator.track || generator;
  const reader = processor.readable.getReader(), writer = generator.writable.getWriter();
  const cancel = () => { void reader.cancel().catch(() => {}); void writer.abort(signal.reason).catch(() => {}); track.stop(); };
  signal.addEventListener('abort', cancel, { once: true });
  const done = (async () => {
    try {
      signal.throwIfAborted();
      for (;;) {
        const next = await cancellable<{ value: VideoFrame; done: boolean }>(reader.read(), signal);
        if (next.done) break;
        let result = next.value;
        try {
          if (result.displayWidth * result.displayHeight * 4 > MEDIA_LIMITS.rawFrameBytes) throw new Error('Track frame budget exceeded');
          result = await cancellableFrame(options.transform(next.value, signal), signal);
          await cancellable(writer.ready, signal);
          await cancellable(writer.write(result), signal);
        } finally { if (result !== next.value) result.close(); next.value.close(); }
      }
      await cancellable(writer.close(), signal);
    } finally {
      link.controller.abort();
      signal.removeEventListener('abort', cancel); link.dispose();
      await reader.cancel().catch(() => {}); reader.releaseLock();
      await writer.abort().catch(() => {}); writer.releaseLock(); track.stop();
    }
  })();
  return { track, done, close: async () => { link.controller.abort(); cancel(); await done.catch(() => {}); } };
}
