import { CodecNegotiator } from './codec-negotiator';
import type { CodecCandidate, MediaPath, Support } from './types';

export interface PolicyContext {
  direct: Support;
  path: MediaPath;
  candidates: readonly CodecCandidate[];
  requiresProcessing?: boolean;
  samplesPlayable?: boolean;
  videoPlayable?: boolean;
  audioConversionAvailable?: boolean;
  preserveTracks?: boolean;
  sourceDecode?: Support;
  failure?: 'authorization' | 'source-changed' | 'network' | 'cancelled' | 'unsupported';
}
export type PlaybackPlan = { kind: 'native-direct' | 'remux' | 'audio-convert' | 'decode-render' | 'existing-fallback' | 'client-transcode';
  reason: string; candidate?: CodecCandidate };

export class TranscodingPolicy {
  constructor(private negotiator = new CodecNegotiator()) {}
  decide(context: PolicyContext): PlaybackPlan {
    if (context.failure && context.failure !== 'unsupported') return { kind: 'existing-fallback', reason: context.failure };
    if (!context.requiresProcessing && context.direct !== 'unsupported') return { kind: 'native-direct', reason: 'original-playable' };
    if (context.preserveTracks === false) return { kind: 'existing-fallback', reason: 'track-preservation-unavailable' };
    if (!context.requiresProcessing && context.samplesPlayable) return { kind: 'remux', reason: 'preserve-original-samples' };
    if (!context.requiresProcessing && context.videoPlayable && context.audioConversionAvailable)
      return { kind: 'audio-convert', reason: 'preserve-original-video' };
    if (context.sourceDecode !== 'supported') return { kind: 'existing-fallback', reason: 'source-decoder-unavailable' };
    const candidate = this.negotiator.select(context.candidates, context.path);
    return candidate ? { kind: 'client-transcode', candidate, reason: 'compatible-output-required' }
      : { kind: 'existing-fallback', reason: 'no-feasible-client-configuration' };
  }
}
