import { MediaCapabilityDetector } from './capability-detector';
import { RuntimePerformanceMonitor } from './runtime-performance-monitor';
import { cancellable, MEDIA_LIMITS, waitUntil, type MediaEnvironment, type HardwareExecution } from './types';

/** Explicit bounded encode/decode trial; support and speed never assert hardware execution. */
export class HardwareAccelerationProbe {
  constructor(private env: MediaEnvironment = globalThis) {}
  async run(config: VideoEncoderConfig, options: { frames?: number; signal?: AbortSignal; timeoutMs?: number; minimumDurationMs?: number;
    pace?: boolean; drawFrame?: (canvas: OffscreenCanvas | HTMLCanvasElement, index: number) => void } = {}) {
    const controller = new AbortController(), signal = controller.signal;
    const cancel = () => controller.abort(options.signal?.reason);
    options.signal?.addEventListener('abort', cancel, { once: true });
    if (options.signal?.aborted) cancel();
    const timer = setTimeout(() => controller.abort(new DOMException('Codec trial timed out', 'TimeoutError')), options.timeoutMs || 10000);
    const monitor = new RuntimePerformanceMonitor();
    const evidence = await new MediaCapabilityDetector(this.env).video(config, 'encode', signal).catch(error => {
      clearTimeout(timer); options.signal?.removeEventListener('abort', cancel); throw error;
    });
    let encoder: VideoEncoder | undefined, decoder: VideoDecoder | undefined, initialized = false;
    let encoded = 0, decoded = 0, queue = Promise.resolve(), pending = 0, pendingBytes = 0;
    const encodeTimes = new Map<number, number>(), decodeTimes = new Map<number, number>();
    const fail = (error: unknown) => { if (!signal.aborted) controller.abort(error); };
    const result = (error?: string) => ({ ...evidence, execution: 'unknown' as HardwareExecution,
      initialized, completed: !error && encoded > 0 && decoded > 0, error, metrics: monitor.snapshot() });
    try {
      if (evidence.support !== 'supported') return result(evidence.reason || 'configuration-unsupported');
      if (config.width * config.height * 4 > MEDIA_LIMITS.rawFrameBytes) return result('Frame budget exceeded');
      if (!this.env.VideoFrame || !this.env.VideoDecoder) return result('Frame or decoder API unavailable');
      const canvas = this.env.OffscreenCanvas ? new this.env.OffscreenCanvas(config.width, config.height)
        : this.env.document?.createElement('canvas');
      if (!canvas) return result('Canvas unavailable');
      canvas.width = config.width; canvas.height = config.height;
      // Allocate a real canvas surface; uninitialized canvases can yield empty frames.
      canvas.getContext?.('2d')?.clearRect(0, 0, config.width, config.height);
      decoder = new this.env.VideoDecoder({ error: fail, output: (frame: VideoFrame) => {
        monitor.record('decode', performance.now() - (decodeTimes.get(frame.timestamp) ?? performance.now()));
        decodeTimes.delete(frame.timestamp); decoded++; frame.close();
      } });
      encoder = new this.env.VideoEncoder({ error: fail,
        output: (chunk: EncodedVideoChunk, metadata: EncodedVideoChunkMetadata) => {
          if (signal.aborted) return;
          monitor.record('encode', performance.now() - (encodeTimes.get(chunk.timestamp) ?? performance.now()));
          encodeTimes.delete(chunk.timestamp); encoded++;
          if (++pending > MEDIA_LIMITS.frames || (pendingBytes += chunk.byteLength) > MEDIA_LIMITS.encodedBytes) {
            fail(new Error('Probe output budget exceeded')); return;
          }
          queue = queue.then(async () => {
            signal.throwIfAborted();
            if (decoder.state === 'unconfigured') {
              if (!metadata.decoderConfig) throw new Error('Encoder omitted decoder configuration');
              const requested = { ...metadata.decoderConfig, optimizeForLatency: true, hardwareAcceleration: config.hardwareAcceleration || 'prefer-hardware' };
              const supported = await new MediaCapabilityDetector(this.env).video(requested, 'decode', signal);
              if (supported.support !== 'supported') throw new Error('Round-trip decoder unsupported');
              decoder.configure(requested);
            }
            await waitUntil(() => decoder.decodeQueueSize < MEDIA_LIMITS.frames, signal);
            if (decodeTimes.size >= 128) throw new Error('Probe decoder budget exceeded');
            decodeTimes.set(chunk.timestamp, performance.now()); decoder.decode(chunk);
          }).catch(fail).finally(() => { pending--; pendingBytes -= chunk.byteLength; });
        },
      });
      encoder.configure({ ...config, hardwareAcceleration: config.hardwareAcceleration || 'prefer-hardware' });
      initialized = true;
      monitor.reset();
      const fps = config.framerate || 30, count = Math.max(1, Math.min(108000, options.frames || 60));
      const started = performance.now(), minimum = Math.max(0, Math.min(30000, options.minimumDurationMs || 0));
      let submitted = 0;
      for (let i = 0; i < count || performance.now() - started < minimum; i++) {
        if (i >= 108000) throw new Error('Codec trial frame budget exceeded');
        if (options.pace && i * 1000 / fps > performance.now() - started)
          await cancellable(new Promise(resolve => setTimeout(resolve, i * 1000 / fps - (performance.now() - started))), signal, options.timeoutMs || 10000);
        // encodeQueueSize can reach zero before native codec work completes.
        // Reserve credits until output arrives so a later callback batch still
        // fits the bounded encoded queue.
        await waitUntil(() => encoder.encodeQueueSize < 2 && encodeTimes.size + pending < MEDIA_LIMITS.frames, signal);
        const timestamp = Math.round(i * 1e6 / fps);
        if (encodeTimes.size >= 128) throw new Error('Probe encoder budget exceeded');
        options.drawFrame?.(canvas, i);
        const frame = new this.env.VideoFrame(canvas, { timestamp, duration: Math.round(1e6 / fps) });
        try { encodeTimes.set(timestamp, performance.now()); encoder.encode(frame, { keyFrame: i === 0 }); submitted++; }
        finally { frame.close(); }
        monitor.observeQueue(encoder.encodeQueueSize);
      }
      await cancellable(encoder.flush(), signal);
      await cancellable(queue, signal);
      signal.throwIfAborted();
      if (decoder.state === 'configured') await cancellable(decoder.flush(), signal);
      signal.throwIfAborted(); monitor.observeQueue(0);
      return result(encoded !== submitted || decoded !== submitted ? 'Incomplete codec trial' : undefined);
    } catch (error) {
      if (options.signal?.aborted) throw options.signal.reason;
      return result(error instanceof Error ? error.message : String(error));
    } finally {
      controller.abort(); clearTimeout(timer); options.signal?.removeEventListener('abort', cancel);
      if (encoder && encoder.state !== 'closed') encoder.close();
      if (decoder && decoder.state !== 'closed') decoder.close();
      encodeTimes.clear(); decodeTimes.clear();
    }
  }
}
