import { validNumber } from './types';

type Stage = 'decode' | 'encode' | 'process';
type StageSamples = { frames: number; values: number[] };
export interface NetworkObservation { rttMs?: number; packetLoss?: number; availableBitrate?: number }
export interface RuntimeObservation extends NetworkObservation {
  targetFps: number; encodeFps?: number; decodeFps?: number; queueDepth?: number;
  droppedFrames?: number; totalFrames?: number; demandBitrate?: number; active?: boolean;
  processingLimited?: boolean; networkLimited?: boolean;
}
export type Adaptation = { direction: 'down' | 'up'; bottleneck: 'network' | 'processing' | 'mixed' | 'none';
  bitrateFactor: number; fpsFactor: number; resolutionFactor: number };

/** All values are observed or unknown; no hardware inference from UA, GPU names or throughput. */
export class RuntimePerformanceMonitor {
  private readonly now: () => number;
  private readonly limit: number;
  private started: number;
  private stages: Record<Stage, StageSamples>;
  private network: NetworkObservation = {};
  private queueDepth = 0;
  private droppedFrames = 0;
  private utilization: { cpu: number | null; gpu: number | null; source: string } | null = null;
  private pressure = '';
  private streak = 0;
  private healthy = 0;
  private lastChange = -Infinity;
  private lastObservation = -Infinity;
  constructor(options: { now?: () => number; sampleLimit?: number } = {}) {
    this.now = options.now || (() => performance.now());
    this.limit = Math.max(1, Math.min(1024, options.sampleLimit || 256));
    this.reset();
  }
  reset() {
    this.started = this.now();
    this.stages = { decode: { frames: 0, values: [] }, encode: { frames: 0, values: [] }, process: { frames: 0, values: [] } };
    this.network = {}; this.queueDepth = this.droppedFrames = this.streak = this.healthy = 0;
    this.pressure = ''; this.utilization = null; this.lastChange = this.lastObservation = -Infinity;
  }
  record(stage: Stage, latencyMs: number, frames = 1) {
    if (!validNumber(latencyMs) || !validNumber(frames, 1)) return;
    const samples = this.stages[stage]; samples.frames += frames; samples.values.push(latencyMs);
    if (samples.values.length > this.limit) samples.values.shift();
  }
  observeQueue(depth: number) { if (validNumber(depth)) this.queueDepth = depth; }
  observeDropped(frames: number) { if (validNumber(frames)) this.droppedFrames = frames; }
  observeNetwork(observation: NetworkObservation) {
    for (const key of ['rttMs', 'packetLoss', 'availableBitrate'] as const) {
      const value = observation[key];
      if (validNumber(value) && (key !== 'packetLoss' || value <= 1)) this.network[key] = value;
      else delete this.network[key];
    }
  }
  observeUtilization(cpu: number | null, gpu: number | null, source: string) {
    if (!source || (cpu !== null && (!validNumber(cpu) || cpu > 100)) ||
      (gpu !== null && (!validNumber(gpu) || gpu > 100))) return;
    this.utilization = { cpu, gpu, source };
  }
  snapshot() {
    const elapsedMs = Math.max(0, this.now() - this.started);
    const summarize = (stage: Stage) => {
      const s = this.stages[stage], sorted = [...s.values].sort((a, b) => a - b);
      return { frames: s.frames, samples: sorted.length, fps: elapsedMs ? s.frames * 1000 / elapsedMs : 0,
        averageMs: sorted.length ? sorted.reduce((sum, n) => sum + n, 0) / sorted.length : 0,
        p95Ms: sorted.length ? sorted[Math.ceil(sorted.length * .95) - 1] : 0 };
    };
    return { elapsedMs, encode: summarize('encode'), decode: summarize('decode'), process: summarize('process'),
      encoderQueueDepth: this.queueDepth, droppedFrames: this.droppedFrames,
      cpuUsage: this.utilization?.cpu ?? null, gpuVideoUtilization: this.utilization?.gpu ?? null,
      utilizationSource: this.utilization?.source ?? null,
      network: { rttMs: this.network.rttMs ?? null, packetLoss: this.network.packetLoss ?? null,
        availableBitrate: this.network.availableBitrate ?? null } };
  }
  adapt(sample: RuntimeObservation): Adaptation | null {
    const now = this.now();
    if (sample.active === false || !validNumber(sample.targetFps, 1)) { this.streak = this.healthy = 0; this.pressure = ''; return null; }
    if (now - this.lastObservation < 500) return null;
    this.lastObservation = now;
    const network = sample.networkLimited === true || (validNumber(sample.availableBitrate, 1) && validNumber(sample.demandBitrate, 1) &&
      sample.availableBitrate < sample.demandBitrate * .85) || sample.packetLoss > .03;
    const processing = sample.processingLimited === true || sample.queueDepth >= 3 || (sample.processingLimited !== false && (
      (sample.encodeFps !== undefined && sample.encodeFps < sample.targetFps * .85) ||
      (sample.decodeFps !== undefined && sample.decodeFps < sample.targetFps * .85) ||
      (sample.totalFrames >= 30 && sample.droppedFrames / sample.totalFrames >= .15)));
    const pressure = network && processing ? 'mixed' : network ? 'network' : processing ? 'processing' : '';
    this.streak = pressure && pressure === this.pressure ? this.streak + 1 : pressure ? 1 : 0;
    this.pressure = pressure; this.healthy = pressure ? 0 : this.healthy + 1;
    if (now - this.lastChange < 5000) return null;
    if (this.streak >= 3) {
      this.streak = 0; this.lastChange = now;
      return { direction: 'down', bottleneck: pressure as Adaptation['bottleneck'], bitrateFactor: .8,
        fpsFactor: processing ? .8 : 1, resolutionFactor: processing ? .8 : 1 };
    }
    // Unknown measurements are not evidence of recovery.
    if (this.healthy >= 10 && validNumber(sample.encodeFps, sample.targetFps) && validNumber(sample.decodeFps, sample.targetFps) &&
      validNumber(sample.availableBitrate, (sample.demandBitrate || Infinity) * 1.25)) {
      this.healthy = 0; this.lastChange = now;
      return { direction: 'up', bottleneck: 'none', bitrateFactor: 1.1, fpsFactor: 1.1, resolutionFactor: 1.1 };
    }
    return null;
  }
}
