import type { CodecCandidate, MediaPath } from './types';

export function measuredSoftware(candidate: CodecCandidate): boolean {
  const p = candidate.performance;
  return !!p && Number.isFinite(p.elapsedMs) && p.elapsedMs >= 1000 && p.frames >= 15 && Number.isFinite(p.fps) &&
    candidate.fps > 0 && candidate.fps <= 15 && p.targetFps >= candidate.fps && p.targetFps <= 15 &&
    Math.min(p.fps, p.frames * 1000 / p.elapsedMs) >= p.targetFps * 1.25 &&
    p.codecString === candidate.codecString && p.width === candidate.width && p.height === candidate.height &&
    candidate.width > 0 && candidate.height > 0 && candidate.width <= 640 && candidate.height <= 360;
}

export class CodecNegotiator {
  select(candidates: readonly CodecCandidate[], path: MediaPath): CodecCandidate | undefined {
    return candidates.filter(candidate => {
      if (candidate.playback !== 'supported' || candidate.transport !== 'supported' ||
        candidate.decode !== 'supported' || candidate.encode !== 'supported' || candidate.codec === 'unknown') return false;
      if (path === 'webrtc-rtp' && candidate.remote !== true) return false;
      const software = candidate.preference === 'prefer-software' || candidate.execution === 'confirmed-software';
      return !software || measuredSoftware(candidate);
    }).map((candidate, index) => {
      const software = candidate.preference === 'prefer-software' || candidate.execution === 'confirmed-software';
      const av1Hardware = candidate.codec === 'av1' && candidate.remote === true && candidate.execution === 'confirmed-hardware';
      const priority = software ? 10 : av1Hardware ? 0 : candidate.codec === 'avc' ? 1 : candidate.codec === 'hevc' ? 2 : 3;
      return { candidate, priority, index };
    }).sort((a, b) => a.priority - b.priority || a.index - b.index)[0]?.candidate;
  }
}
