import { cancellable, MEDIA_LIMITS, type BoundedMediaSource } from '../types';

export interface RangeResponse { status: number; data: ArrayBuffer; headers: Record<string, unknown> | { get(name: string): unknown } }
export type RangeRequest = (start: number, endInclusive: number, signal: AbortSignal) => Promise<RangeResponse>;

export function linkAbort(...parents: (AbortSignal | undefined)[]) {
  const controller = new AbortController();
  const listeners = parents.filter(Boolean).map(parent => {
    const abort = () => controller.abort(parent.reason);
    parent.addEventListener('abort', abort, { once: true });
    if (parent.aborted) abort();
    return () => parent.removeEventListener('abort', abort);
  });
  return { controller, dispose: () => listeners.forEach(remove => remove()) };
}

/** The injected Photos request must validate headers before consuming its body. */
export class HttpRangeSource implements BoundedMediaSource {
  private lifetime = new AbortController();
  private revision: string | undefined;
  private total: number | undefined;
  constructor(readonly identity: string, private request: RangeRequest, readonly nativeUrl?: string) {}
  get size() { return this.total; }
  async read(start: number, endExclusive: number, signal?: AbortSignal): Promise<Uint8Array<ArrayBuffer>> {
    this.lifetime.signal.throwIfAborted(); signal?.throwIfAborted();
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(endExclusive) || start < 0 || endExclusive <= start ||
      endExclusive - start > MEDIA_LIMITS.readBytes) throw new Error('HTTP range budget exceeded');
    const end = this.total === undefined ? endExclusive : Math.min(endExclusive, this.total);
    if (start >= end) return new Uint8Array();
    const link = linkAbort(this.lifetime.signal, signal);
    try {
      const response = await cancellable(this.request(start, end - 1, link.controller.signal), link.controller.signal);
      const header = (name: string) => String(typeof response.headers.get === 'function'
        ? response.headers.get(name) || '' : response.headers[name] || '');
      const range = /^bytes (\d+)-(\d+)\/(\d+)$/.exec(header('content-range'));
      if (response.status !== 206 || !range || Number(range[1]) !== start || Number(range[2]) >= end ||
        Number(range[2]) < start || !Number.isSafeInteger(Number(range[3])) || Number(range[3]) <= Number(range[2]))
        throw new Error('Server ignored or returned invalid Range');
      const total = Number(range[3]), revision = header('etag');
      if ((this.total !== undefined && this.total !== total) || (this.revision !== undefined && this.revision !== revision))
        throw new Error('Media source changed during playback');
      if (!(response.data instanceof ArrayBuffer) || response.data.byteLength !== Number(range[2]) - start + 1 ||
        response.data.byteLength > MEDIA_LIMITS.readBytes) throw new Error('Invalid Range body length');
      this.total = total; this.revision = revision;
      return new Uint8Array(response.data);
    } finally { link.controller.abort(); link.dispose(); }
  }
  close() { this.lifetime.abort(); }
}
