import { MediaCapabilityDetector } from './capability-detector';
import { RuntimePerformanceMonitor } from './runtime-performance-monitor';
import { measuredSoftware } from './codec-negotiator';
import { cancellable, cancellableFrame, MEDIA_LIMITS, waitUntil, type MediaEnvironment, type ThroughputEvidence } from './types';

export class MediaCodecFailure extends Error {
  constructor(readonly stage: 'encode' | 'decode' | 'configure', error: unknown) {
    super(`${stage}: ${error instanceof Error ? error.message : String(error)}`); this.name = 'MediaCodecFailure';
  }
}

export interface TranscodeOptions {
  decoderConfig: VideoDecoderConfig;
  encoderConfig: VideoEncoderConfig;
  chunks: (signal: AbortSignal) => AsyncIterable<EncodedVideoChunk>;
  sink: (chunk: EncodedVideoChunk, metadata: EncodedVideoChunkMetadata) => Promise<void>;
  process?: (frame: VideoFrame, signal: AbortSignal) => Promise<VideoFrame>;
  signal?: AbortSignal;
  startTimestamp?: number;
  onMetrics?: (metrics: ReturnType<RuntimePerformanceMonitor['snapshot']>) => void;
}

/** One bounded attempt. The caller owns demux, mux and any restart after a failed attempt. */
export class BoundedVideoTranscoder {
  private controller?: AbortController;
  constructor(private env: MediaEnvironment = globalThis) {}
  close() { this.controller?.abort(); }
  async runWithFallback(options: TranscodeOptions, fallback: {
    softwarePerformance: ThroughputEvidence; resetOutput: () => Promise<void>;
  }) {
    try { return await this.run(options); }
    catch (error) {
      options.signal?.throwIfAborted();
      const config = options.encoderConfig;
      const decoder = options.decoderConfig;
      if (!(error instanceof MediaCodecFailure) || config.hardwareAcceleration === 'prefer-software' ||
        !(decoder.codedWidth > 0 && decoder.codedHeight > 0 && decoder.codedWidth <= 640 && decoder.codedHeight <= 360) ||
        !measuredSoftware({ codec: 'avc', codecString: config.codec, playback: 'supported', transport: 'supported',
          decode: 'supported', encode: 'supported', preference: 'prefer-software', execution: 'unknown',
          width: config.width, height: config.height, fps: config.framerate, performance: fallback.softwarePerformance })) throw error;
      await cancellable(fallback.resetOutput(), options.signal);
      return this.run({ ...options,
        decoderConfig: { ...options.decoderConfig, hardwareAcceleration: 'prefer-software' },
        encoderConfig: { ...config, hardwareAcceleration: 'prefer-software' } });
    }
  }
  async run(options: TranscodeOptions) {
    if (this.controller) throw new Error('Media transcoder is already running');
    const controller = this.controller = new AbortController(), signal = controller.signal;
    const cancel = () => controller.abort(options.signal?.reason);
    options.signal?.addEventListener('abort', cancel, { once: true });
    if (options.signal?.aborted) cancel();
    const monitor = new RuntimePerformanceMonitor();
    const detector = new MediaCapabilityDetector(this.env);
    let decoder: VideoDecoder | undefined, encoder: VideoEncoder | undefined;
    let iterator: AsyncIterator<EncodedVideoChunk> | undefined;
    const ownedFrames = new Set<VideoFrame>(), decodeTimes = new Map<number, number>(), encodeTimes = new Map<number, number>();
    let processing = Promise.resolve(), writing = Promise.resolve(), rawBytes = 0, rawCount = 0, outputBytes = 0, outputCount = 0;
    let encodedFrames = 0, lastEncodedTimestamp = -Infinity;
    const fail = (error: unknown) => { if (!signal.aborted) controller.abort(error); };
    const sampling = options.onMetrics ? setInterval(() => {
      try { options.onMetrics(monitor.snapshot()); } catch (error) { fail(error); }
    }, 1000) : undefined;
    try {
      const requestedDecoder = { optimizeForLatency: true, ...options.decoderConfig };
      const input = await detector.video(requestedDecoder, 'decode', signal);
      const output = await detector.video(options.encoderConfig, 'encode', signal);
      if (input.support !== 'supported' || output.support !== 'supported') throw new MediaCodecFailure('configure', 'Media codec configuration unsupported');
      encoder = new this.env.VideoEncoder({
        error: (error: unknown) => fail(new MediaCodecFailure('encode', error)),
        output: (chunk: EncodedVideoChunk, metadata: EncodedVideoChunkMetadata) => {
          if (signal.aborted) return;
          monitor.record('encode', performance.now() - (encodeTimes.get(chunk.timestamp) ?? performance.now()));
          encodeTimes.delete(chunk.timestamp);
          if (++outputCount > MEDIA_LIMITS.frames || (outputBytes += chunk.byteLength) > MEDIA_LIMITS.encodedBytes) {
            fail(new Error('Encoded output budget exceeded')); return;
          }
          writing = writing.then(async () => {
            signal.throwIfAborted();
            await cancellable(options.sink(chunk, metadata), signal);
          }).catch(fail).finally(() => { outputCount--; outputBytes -= chunk.byteLength; });
        },
      });
      try { encoder.configure(output.configuration as VideoEncoderConfig || options.encoderConfig); }
      catch (error) { throw new MediaCodecFailure('configure', error); }
      decoder = new this.env.VideoDecoder({
        error: (error: unknown) => fail(new MediaCodecFailure('decode', error)),
        output: (frame: VideoFrame) => {
          if (signal.aborted) { frame.close(); return; }
          const bytes = frame.allocationSize?.() || frame.displayWidth * frame.displayHeight * 4;
          monitor.record('decode', performance.now() - (decodeTimes.get(frame.timestamp) ?? performance.now()));
          decodeTimes.delete(frame.timestamp);
          rawCount++; rawBytes += bytes;
          if (rawCount > MEDIA_LIMITS.frames || rawBytes > MEDIA_LIMITS.rawFrameBytes) {
            rawCount--; rawBytes -= bytes; frame.close(); fail(new Error('Decoded frame budget exceeded')); return;
          }
          ownedFrames.add(frame);
          processing = processing.then(async () => {
            let transformed = frame;
            try {
              signal.throwIfAborted();
              if (frame.timestamp < (options.startTimestamp ?? -Infinity)) return;
              const fps = options.encoderConfig.framerate;
              if (fps && frame.timestamp - lastEncodedTimestamp < 1e6 / fps - 1) { monitor.observeDropped(++dropped); return; }
              const started = performance.now();
              if (options.process) transformed = await cancellableFrame(options.process(frame, signal), signal);
              if (transformed !== frame) ownedFrames.add(transformed);
              monitor.record('process', performance.now() - started);
              await waitUntil(() => encoder.encodeQueueSize < MEDIA_LIMITS.frames && outputCount < MEDIA_LIMITS.frames, signal);
              signal.throwIfAborted();
              if (encodeTimes.size >= 128) throw new Error('Encoder timestamp budget exceeded');
              encodeTimes.set(transformed.timestamp, performance.now());
              encoder.encode(transformed, { keyFrame: encodedFrames++ % Math.max(1, Math.round((fps || 30) * 2)) === 0 });
              lastEncodedTimestamp = transformed.timestamp;
              monitor.observeQueue(encoder.encodeQueueSize);
            } finally {
              if (transformed !== frame) { transformed.close(); ownedFrames.delete(transformed); }
              frame.close(); ownedFrames.delete(frame); rawCount--; rawBytes -= bytes;
            }
          }).catch(fail);
        },
      });
      try { decoder.configure(input.configuration as VideoDecoderConfig || requestedDecoder); }
      catch (error) { throw new MediaCodecFailure('configure', error); }
      let dropped = 0;
      iterator = options.chunks(signal)[Symbol.asyncIterator]();
      for (;;) {
        const next = await cancellable(iterator.next(), signal);
        if (next.done) break;
        // decodeQueueSize excludes decoder-internal reordering. Reserve a raw-frame
        // credit for every submitted timestamp until its output has been consumed.
        await waitUntil(() => decoder.decodeQueueSize < MEDIA_LIMITS.frames &&
          decodeTimes.size + rawCount < MEDIA_LIMITS.frames && outputCount < 2, signal);
        if (next.value.byteLength > MEDIA_LIMITS.encodedBytes) throw new Error('Encoded input budget exceeded');
        if (decodeTimes.size >= 128) throw new Error('Decoder timestamp budget exceeded');
        decodeTimes.set(next.value.timestamp, performance.now());
        decoder.decode(next.value);
      }
      await cancellable(decoder.flush(), signal);
      await cancellable(processing, signal);
      signal.throwIfAborted();
      await cancellable(encoder.flush(), signal);
      await cancellable(writing, signal);
      signal.throwIfAborted();
      monitor.observeQueue(0);
      return monitor.snapshot();
    } finally {
      clearInterval(sampling);
      controller.abort();
      if (decoder && decoder.state !== 'closed') decoder.close();
      if (encoder && encoder.state !== 'closed') encoder.close();
      for (const frame of ownedFrames) frame.close();
      ownedFrames.clear(); decodeTimes.clear(); encodeTimes.clear();
      if (iterator?.return) await cancellable(Promise.resolve().then(() => iterator.return()), undefined, 1000).catch(() => {});
      options.signal?.removeEventListener('abort', cancel);
      this.controller = undefined;
    }
  }
}
