import { cancellable, MEDIA_LIMITS, type BoundedMediaSource } from './types';

const text = new TextDecoder('ascii');
const containers = new Set(['moov', 'trak', 'mdia', 'minf', 'stbl']);
const tables = new Set(['stsz', 'stz2', 'stts', 'ctts', 'stsc', 'stco', 'co64', 'stss']);

/** Bound compressed table counts before MP4Box expands them into sample objects. */
function validateIndex(bytes: Uint8Array) {
  const view = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  let samples = 0, tracks = 0, boxes = 0;
  const walk = (start: number, end: number, depth: number) => {
    if (depth > 12) throw new Error('MP4 metadata nesting budget exceeded');
    while (start < end) {
      if (++boxes > MEDIA_LIMITS.indexSamples || end - start < 8) throw new Error('Invalid MP4 metadata box');
      const type = text.decode(bytes.subarray(start + 4, start + 8));
      let size = view.getUint32(start), header = 8;
      if (size === 1) {
        if (end - start < 16) throw new Error('Invalid MP4 box size');
        size = Number(view.getBigUint64(start + 8)); header = 16;
      } else if (size === 0) size = end - start;
      if (!Number.isSafeInteger(size) || size < header || size > end - start) throw new Error('Invalid MP4 box size');
      if (type === 'cmov') throw new Error('Compressed MP4 metadata is unsupported');
      if (type === 'trak' && ++tracks > 16) throw new Error('Media track index budget exceeded');
      if (tables.has(type)) {
        const countOffset = start + header + (type === 'stsz' || type === 'stz2' ? 8 : 4);
        if (countOffset + 4 > start + size) throw new Error('Truncated MP4 sample table');
        const count = view.getUint32(countOffset);
        if (type === 'stsz' || type === 'stz2') samples += count;
        if (count > MEDIA_LIMITS.indexSamples || samples > MEDIA_LIMITS.indexSamples) throw new Error('Media index budget exceeded');
      }
      if (containers.has(type)) walk(start + header, start + size, depth + 1);
      start += size;
    }
  };
  walk(0, bytes.length, 0);
}

/** Locate ftyp/moov using box headers; never read mdat or allocate the whole file. */
export async function readMp4Metadata(source: BoundedMediaSource, signal?: AbortSignal) {
  const boxes: { offset: number; bytes: Uint8Array<ArrayBuffer> }[] = [];
  let readBytes = 0, offset = 0;
  const read = async (start: number, length: number) => {
    if (!Number.isSafeInteger(length) || length <= 0 || readBytes + length > MEDIA_LIMITS.metadataBytes)
      throw new Error('Media metadata budget exceeded');
    const data = new Uint8Array(length);
    for (let done = 0; done < length;) {
      const count = Math.min(length - done, MEDIA_LIMITS.readBytes);
      const part = await cancellable(source.read(start + done, start + done + count, signal), signal);
      if (!part.length || part.length > count) throw new Error('Truncated MP4 metadata');
      data.set(part, done); done += part.length; readBytes += part.length;
    }
    return data;
  };
  for (let index = 0; index < 4096; index++) {
    const header = await read(offset, 8), view = new DataView(header.buffer);
    const type = text.decode(header.subarray(4, 8));
    let size = view.getUint32(0), headerSize = 8;
    if (size === 1) { size = Number(new DataView((await read(offset + 8, 8)).buffer).getBigUint64(0)); headerSize = 16; }
    else if (!size) size = (source.size ?? NaN) - offset;
    if (!Number.isSafeInteger(size) || size < headerSize || !Number.isSafeInteger(offset + size) ||
      (source.size !== undefined && offset + size > source.size)) throw new Error('Invalid MP4 box size');
    if (type === 'ftyp' || type === 'moov') {
      const bytes = await read(offset, size);
      if (type === 'moov') validateIndex(bytes);
      boxes.push({ offset, bytes });
      if (type === 'moov') {
        if (!boxes.some(box => text.decode(box.bytes.subarray(4, 8)) === 'ftyp')) throw new Error('Missing MP4 file type');
        return { boxes, readBytes };
      }
    }
    offset += size;
    if (source.size !== undefined && offset >= source.size) break;
  }
  throw new Error('MP4 metadata not found within the box budget');
}
