import { cancellable, validNumber, type CodecEvidence, type MediaEnvironment, type MediaPath, type Support } from './types';

/** Queries are explicit and configuration-specific; ordinary playback never calls video(). */
export class MediaCapabilityDetector {
  constructor(private env: MediaEnvironment = globalThis) {}

  playback(mime: string, path: MediaPath): Support {
    if (!mime) return 'unknown';
    try {
      if (path === 'mse' || path === 'datachannel-file') {
        const Source = this.env.ManagedMediaSource || this.env.MediaSource;
        return Source?.isTypeSupported ? (Source.isTypeSupported(mime) ? 'supported' : 'unsupported') : 'unsupported';
      }
      if (path === 'webrtc-rtp') return 'unknown';
      const value = this.env.nativeSupport ? this.env.nativeSupport(mime)
        : this.env.document?.createElement('video').canPlayType(mime);
      return value === 'probably' ? 'supported' : value === 'maybe' ? 'unknown' : value === '' ? 'unsupported' : 'unknown';
    } catch { return 'unknown'; }
  }

  async video(config: Record<string, any>, mode: 'decode' | 'encode', signal?: AbortSignal): Promise<CodecEvidence> {
    signal?.throwIfAborted();
    const preference = config.hardwareAcceleration || 'prefer-hardware';
    const base: CodecEvidence = { support: 'unsupported', preference, execution: 'unknown' };
    const API = mode === 'decode' ? this.env.VideoDecoder : this.env.VideoEncoder;
    if (!this.env.isSecureContext || !API?.isConfigSupported) return { ...base, reason: 'api-unavailable' };
    if (typeof config.codec !== 'string' || !config.codec.trim() ||
      ['width', 'height', 'codedWidth', 'codedHeight', 'framerate', 'bitrate'].some(key =>
        config[key] !== undefined && !validNumber(config[key], 1))) return { ...base, reason: 'invalid-configuration' };
    if (config.description?.byteLength > 1024 * 1024) return { ...base, reason: 'configuration-too-large' };
    try {
      const requested = { ...config, hardwareAcceleration: preference };
      const result = await cancellable<{ supported: boolean; config: VideoDecoderConfig | VideoEncoderConfig }>(API.isConfigSupported(requested), signal);
      return { ...base, support: result.supported ? 'supported' : 'unsupported', configuration: result.config };
    } catch (error) {
      signal?.throwIfAborted();
      return { ...base, reason: error instanceof Error ? error.message : 'configuration-rejected' };
    }
  }

  rtp() {
    const get = (api: any) => {
      try { return api?.getCapabilities?.('video')?.codecs || []; } catch { return []; }
    };
    return { sender: get(this.env.RTCRtpSender), receiver: get(this.env.RTCRtpReceiver) };
  }

  async prediction(configuration: MediaDecodingConfiguration, signal?: AbortSignal) {
    signal?.throwIfAborted();
    try {
      const api = this.env.navigator?.mediaCapabilities;
      return api?.decodingInfo ? await cancellable(api.decodingInfo(configuration), signal) : null;
    } catch { signal?.throwIfAborted(); return null; }
  }
}
