import { TranscodingPolicy } from '../transcoding-policy';
import type { BoundedMediaSource, MediaEnvironment } from '../types';
import { HttpRangeSource, type RangeResponse } from './range-source';

export class PhotosHttpAdapter {
  constructor(private environment: MediaEnvironment = globalThis, private request?:
    (resource: string, start: number, end: number, signal: AbortSignal) => Promise<RangeResponse>) {}
  /** Synchronous, with no capability probes, API requests or codec instances. */
  direct(url: string) {
    if (!url.trim()) throw new Error('Empty media URL');
    return { ...new TranscodingPolicy().decide({ direct: 'unknown', path: 'http-file', candidates: [] }), url };
  }
  async source(url: string): Promise<BoundedMediaSource> {
    const origin = this.environment.location?.origin;
    if (!origin) throw new Error('Photos source requires a same-origin browser context');
    const parsed = new URL(url, origin);
    const resource = /^\/v2\/photos\/preview\/(\d+_original\.bin)$/.exec(parsed.pathname)?.[1];
    const id = parsed.pathname === '/v2/photos/preview' ? parsed.searchParams.get('asset_id')
      : /^\/v2\/photos\/assets\/(\d+)\/preview$/.exec(parsed.pathname)?.[1];
    const original = resource || (/^[1-9]\d*$/.test(id || '') ? `${id}_original.bin` : '');
    if (parsed.origin !== origin || !original || !this.request) throw new Error('Unsupported Photos original resource or missing Range adapter');
    return new HttpRangeSource(original, (start, end, signal) => this.request(original, start, end, signal), url);
  }
}
