import { cancellable, MEDIA_LIMITS, type BoundedMediaSource } from '../types';
import { linkAbort } from './range-source';

export interface SharedMediaFile { file_id: string; version: string; [key: string]: unknown }
export interface MediaReceiver {
  fileInfo(file: SharedMediaFile, representation: string, signal?: AbortSignal): Promise<{ size: number }>;
  read(file: SharedMediaFile, start: number, end: number, representation: string, signal?: AbortSignal): Promise<Uint8Array<ArrayBuffer>>;
}
export interface ReceiverSourceOptions {
  /** null delegates deadlines to a receiver that already bounds and retries requests. */
  requestTimeoutMs?: number | null;
}

/** Range facade over the existing Receiver. It never sends raw chunks or controls the connection. */
export class ReceiverMediaSource implements BoundedMediaSource {
  private lifetime = new AbortController();
  readonly identity: string;
  private constructor(private receiver: MediaReceiver, private file: SharedMediaFile, readonly size: number,
    private options: ReceiverSourceOptions) {
    this.identity = `${file.file_id}:${file.version}`;
  }
  static async open(receiver: MediaReceiver, file: SharedMediaFile, signal?: AbortSignal, options: ReceiverSourceOptions = {}) {
    const pending = receiver.fileInfo(file, 'original', signal);
    const info = options.requestTimeoutMs === null ? await pending : await cancellable(pending, signal, options.requestTimeoutMs);
    signal?.throwIfAborted();
    if (!Number.isSafeInteger(info.size) || info.size <= 0) throw new Error('Invalid shared media size');
    return new ReceiverMediaSource(receiver, { ...file }, info.size, options);
  }
  async read(start: number, endExclusive: number, signal?: AbortSignal) {
    this.lifetime.signal.throwIfAborted(); signal?.throwIfAborted();
    if (!Number.isSafeInteger(start) || !Number.isSafeInteger(endExclusive) || start < 0 || endExclusive <= start ||
      endExclusive - start > MEDIA_LIMITS.readBytes || endExclusive > this.size) throw new Error('Shared media range budget exceeded');
    const link = linkAbort(this.lifetime.signal, signal);
    try {
      const pending = this.receiver.read(this.file, start, endExclusive, 'original', link.controller.signal);
      const bytes = this.options.requestTimeoutMs === null ? await pending
        : await cancellable(pending, link.controller.signal, this.options.requestTimeoutMs);
      link.controller.signal.throwIfAborted();
      if (bytes.byteLength !== endExclusive - start) throw new Error('Incomplete verified media range');
      return bytes;
    } finally { link.controller.abort(); link.dispose(); }
  }
  close() { this.lifetime.abort(); }
}
