import { cancellable, MEDIA_LIMITS, type BoundedMediaSource, type CodecFamily, type MediaFormat } from './types';
import { readMp4Metadata } from './mp4-metadata';

export class MediaFormatInspector {
  codecFamily(codec: string): CodecFamily {
    if (/^(avc1|avc3)/i.test(codec)) return 'avc';
    if (/^(hvc1|hev1)/i.test(codec)) return 'hevc';
    if (/^av01/i.test(codec)) return 'av1';
    if (/^(vp8|vp08)/i.test(codec)) return 'vp8';
    if (/^(vp9|vp09)/i.test(codec)) return 'vp9';
    return 'unknown';
  }
  async sniff(source: BoundedMediaSource, signal?: AbortSignal): Promise<MediaFormat['container']> {
    const bytes = await cancellable(source.read(0, Math.min(source.size ?? 4096, 4096), signal), signal);
    const signature = new TextDecoder().decode(bytes.subarray(4, 12));
    if (signature.startsWith('ftyp')) return signature.slice(4).startsWith('qt') ? 'quicktime' : 'mp4';
    if (bytes[0] === 0x1a && bytes[1] === 0x45 && bytes[2] === 0xdf && bytes[3] === 0xa3) {
      const text = new TextDecoder().decode(bytes);
      return text.includes('webm') ? 'webm' : 'matroska';
    }
    return 'unknown';
  }
  /** Existing MP4Box is loaded only on the optional inspection path. */
  async inspect(source: BoundedMediaSource, signal?: AbortSignal): Promise<MediaFormat> {
    return (await this.openMp4(source, signal)).format;
  }
  async openMp4(source: BoundedMediaSource, signal?: AbortSignal) {
    const container = await this.sniff(source, signal);
    if (container !== 'mp4' && container !== 'quicktime') throw new Error(`Container inspection unavailable: ${container}`);
    const metadata = await readMp4Metadata(source, signal);
    const { createFile, DataStream } = await import('mp4box');
    const file = createFile(false);
    let movie: any, failure: Error | undefined;
    file.onReady = info => { movie = info; };
    file.onError = message => { failure = new Error(String(message)); };
    const readBytes = metadata.readBytes;
    try {
      let metadataOffset = 0;
      for (const { bytes } of metadata.boxes) {
        signal?.throwIfAborted();
        const buffer = bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength) as ArrayBuffer & { fileStart: number };
        // Parse a compact metadata-only stream. stco/co64 still contain the
        // original absolute sample offsets used by the bounded source reader.
        buffer.fileStart = metadataOffset; metadataOffset += bytes.byteLength;
        file.appendBuffer(buffer);
        if (failure) throw failure;
      }
      if (!movie) throw new Error('Incomplete MP4 metadata');
      const tracks = movie.tracks.map((track: any) => {
        const entry = file.getTrackById(track.id).mdia.minf.stbl.stsd.entries[0] as any;
        const config = entry.avcC || entry.hvcC || entry.vpcC || entry.av1C;
        let description: Uint8Array<ArrayBuffer> | undefined;
        if (config) { const stream = new DataStream(); config.write(stream); description = new Uint8Array(stream.buffer.slice(8)); }
        return { id: track.id, kind: track.type === 'video' || track.type === 'audio' ? track.type
          : ['text', 'subt', 'sbtl'].includes(track.type) ? 'text' : 'other',
          codec: track.codec, family: this.codecFamily(track.codec), width: track.video?.width, height: track.video?.height,
          sampleRate: track.audio?.sample_rate, channels: track.audio?.channel_count,
          timescale: track.timescale, duration: track.duration / track.timescale, description,
          encrypted: !!entry.sinf || /^(encv|enca)/.test(track.codec) };
      });
      const format: MediaFormat = { container, tracks, duration: movie.duration / movie.timescale, fragmented: movie.isFragmented,
        mime: `video/${container === 'quicktime' ? 'quicktime' : 'mp4'}; codecs="${tracks.map((track: any) => track.codec).join(', ')}"` };
      if (tracks.length > 16 || movie.tracks.some((track: any) => track.nb_samples > MEDIA_LIMITS.indexSamples))
        throw new Error('Media track index budget exceeded');
      file.stop();
      return { file, movie, format, readBytes };
    } catch (error) { file.stop(); throw error; }
  }
}
